fts.index:
function(doc) {
    var fieldsToIndex = [
        "fname", "content", "user", "name", "group", "channel", "dataset", "dtype", "orgType",
        "record", "recordType", "hostname", "ip", "os", "url", "path", "domain",
        "org", "subnet", "asn", "platform", "bio", "subject", "body", "from", "to",
        "description", "password"
    ];
    if(doc.hasOwnProperty("sources")){
      for (var x = 0; x < doc.sources.length; x++){
        index("sources", doc.sources[x], {"store": true})
      }
    }
    if(doc.hasOwnProperty("resolvedAddresses")){
      for (var x = 0; x < doc.resolvedAddresses.length; x++){
        index("resolvedAddresses", doc.resolvedAddresses[x], {"store": true})
      }
    }
    if(doc.hasOwnProperty("ports") && Array.isArray(doc.ports)){
      for (var x = 0; x < doc.ports.length; x++){
        if(doc.ports[x].name){
          index("port", doc.ports[x].name, {"store": true})
        }
      }
    }
    for (var i = 0; i < fieldsToIndex.length; i++) {
        var field = fieldsToIndex[i];
        if (doc.hasOwnProperty(field)) {
            var value = doc[field];
            if (typeof value !== 'undefined') {
                index(field, value, {"store": true});
            }
        }
    }
}
